import React from "react";
import { motion } from "framer-motion";
import { COLLECTIONS } from "./Content";
import { ArrowUpRight } from "lucide-react";

// Card hover animation variants
const cardVariants = {
  initial: { y: 0, scale: 1 },
  hover: {
    y: -8,
    scale: 1.02,
    transition: { duration: 0.3, ease: "easeOut" }
  }
};

// Image zoom variant
const imageVariants = {
  initial: { scale: 1 },
  hover: { scale: 1.1, transition: { duration: 0.8, ease: "easeOut" } }
};

// Arrow button variant
const arrowVariants = {
  initial: { opacity: 0, scale: 0.5, rotate: -45 },
  hover: { opacity: 1, scale: 1, rotate: 0, transition: { duration: 0.3, delay: 0.1 } }
};

// Border glow variant
const borderVariants = {
  initial: { opacity: 0 },
  hover: { opacity: 1, transition: { duration: 0.3 } }
};

// Stagger container for cards
const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.1 }
  }
};

const itemVariants = {
  hidden: { opacity: 0, y: 30 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: "easeOut" }
  }
};

export default function Collections({ onOpenQuote }) {
  return (
    <section id="collections" className="relative px-6 md:px-12 lg:px-32 py-20 md:py-28" style={{ background: "#ffffff" }}>
      <motion.div
        className="flex items-end justify-between flex-wrap gap-8 mb-16"
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true }}
        transition={{ duration: 0.6 }}
      >
        <div className="max-w-2xl">
          <div className="overline mb-5">Our Collections</div>
          <h2 className="font-semibold" style={{ fontSize: "clamp(40px, 5vw, 64px)", lineHeight: 1.1, color: "#1a080a", fontFamily: "Outfit, sans-serif" }}>
            Six fabric series for every kind of <span style={{ color: "#d4af37" }}>celebration</span>.
          </h2>
        </div>
        <p className="max-w-md text-lg" style={{ color: "rgba(26,8,10,0.6)", lineHeight: 1.7 }}>
          Hand-picked, trend-driven and ready in bulk — discover the fabrics decorators across India keep coming back for.
        </p>
      </motion.div>

      <motion.div
        className="grid grid-cols-1 lg:grid-cols-12 gap-8"
        variants={containerVariants}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, margin: "-50px" }}
      >
        {COLLECTIONS.map((c, index) => (
          <motion.a
            key={c.id}
            href="#contact"
            variants={itemVariants}
            whileHover="hover"
            initial="initial"
            className={`group relative overflow-hidden rounded-xl ${c.span} ${c.height} block`}
            style={{ border: "2px solid rgba(212,175,55,0.3)" }}
          >
            {/* Animated card wrapper */}
            <motion.div
              variants={cardVariants}
              className="relative w-full h-full"
            >
              {/* Image with zoom effect */}
              <motion.img
                src={c.image}
                alt={c.title}
                loading="lazy"
                className="absolute inset-0 w-full h-full object-cover"
                variants={imageVariants}
              />

              {/* Gradient overlay */}
              <div className="absolute inset-0" style={{ background: "linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.6) 100%)" }} />

              {/* Top badges */}
              <div className="absolute top-4 left-4 right-4 flex justify-between items-start">
                <motion.span
                  className="text-xs font-semibold tracking-wider uppercase px-3 py-1 rounded-full"
                  style={{ background: "rgba(212,175,55,0.9)", color: "#1a080a" }}
                  whileHover={{ scale: 1.05 }}
                >
                  {c.overline}
                </motion.span>

                {/* Animated arrow button */}
                <motion.span
                  className="w-10 h-10 rounded-full flex items-center justify-center"
                  style={{ background: "rgba(212,175,55,0.95)" }}
                  variants={arrowVariants}
                >
                  <ArrowUpRight size={18} color="#1a080a" />
                </motion.span>
              </div>

              {/* Bottom content */}
              <div className="absolute bottom-0 left-0 right-0 p-6 md:p-8">
                <h3 className="serif mb-2" style={{ fontSize: "clamp(20px, 2.4vw, 32px)", lineHeight: 1.1, fontWeight: 400, color: "#ffffff" }}>{c.title}</h3>
                <p style={{ color: "rgba(255,255,255,0.85)", fontSize: 13, lineHeight: 1.5, maxWidth: 460 }}>{c.desc}</p>
              </div>

              {/* Gold border glow on hover */}
              <motion.div
                className="absolute inset-0 pointer-events-none"
                style={{ boxShadow: "inset 0 0 0 3px #d4af37" }}
                variants={borderVariants}
              />
            </motion.div>
          </motion.a>
        ))}
      </motion.div>

      <motion.div
        className="mt-14 flex justify-center"
        initial={{ opacity: 0, y: 20 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true }}
        transition={{ duration: 0.5, delay: 0.3 }}
      >
        <motion.button
          onClick={onOpenQuote}
          className="btn-gold text-lg px-10 py-4"
          whileHover={{ scale: 1.05, y: -2 }}
          whileTap={{ scale: 0.98 }}
        >
          Request a Custom Quote
        </motion.button>
      </motion.div>
    </section>
  );
}
